import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"ストレージ分析","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. ストレージ分析の表示方法","slug":"_1-ストレージ分析の表示方法","link":"#_1-ストレージ分析の表示方法","children":[]},{"level":2,"title":"2. 画面構成とビジュアル表示","slug":"_2-画面構成とビジュアル表示","link":"#_2-画面構成とビジュアル表示","children":[{"level":3,"title":"左ペイン：ツリーマップ（Treemap）表示","slug":"左ペイン-ツリーマップ-treemap-表示","link":"#左ペイン-ツリーマップ-treemap-表示","children":[]},{"level":3,"title":"右ペイン：サイズ降順一覧","slug":"右ペイン-サイズ降順一覧","link":"#右ペイン-サイズ降順一覧","children":[]}]},{"level":2,"title":"3. ナビゲーションと操作方法","slug":"_3-ナビゲーションと操作方法","link":"#_3-ナビゲーションと操作方法","children":[]},{"level":2,"title":"4. 集計基準とリアルタイム同期","slug":"_4-集計基準とリアルタイム同期","link":"#_4-集計基準とリアルタイム同期","children":[{"level":3,"title":"集計の範囲と基準","slug":"集計の範囲と基準","link":"#集計の範囲と基準","children":[]},{"level":3,"title":"リアルタイム同期と自動復帰","slug":"リアルタイム同期と自動復帰","link":"#リアルタイム同期と自動復帰","children":[]}]}],"relativePath":"ja-JP/user-guide/space-analyzer.md","filePath":"ja-JP/user-guide/space-analyzer.md","lastUpdated":1791112464000}`),a={name:`ja-JP/user-guide/space-analyzer.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ストレージ分析" tabindex="-1">ストレージ分析 <a class="header-anchor" href="#ストレージ分析" aria-label="Permalink to “ストレージ分析”">​</a></h1><p>Lertaro は、ディスク・フォルダーの<strong>ストレージ分析（Space Analyzer）</strong>機能を内蔵しています。時間を要する全セクタの物理スキャンを毎回行う従来のツールとは異なり、Lertaro がバックグラウンドですでに構築したインメモリインデックスツリーをそのまま活用するため、数百万件のファイルが存在するドライブでも数秒で容量内訳を可視化できます。</p><h2 id="_1-ストレージ分析の表示方法" tabindex="-1">1. ストレージ分析の表示方法 <a class="header-anchor" href="#_1-ストレージ分析の表示方法" aria-label="Permalink to “1. ストレージ分析の表示方法”">​</a></h2><ul><li><strong>自動表示</strong>：Lertaro のメイン検索ウィンドウ（<code>Ctrl+F</code>）を開き、<strong>検索ボックスを空のまま</strong>にすると、ストレージ分析が自動的にホーム画面として表示されます。</li><li><strong>検索との即時切り替え</strong>：検索ボックスに文字を入力すると即座に通常の検索結果一覧に切り替わり、<code>Escape</code> や Backspace で空にするとストレージ分析へ戻ります。</li></ul><h2 id="_2-画面構成とビジュアル表示" tabindex="-1">2. 画面構成とビジュアル表示 <a class="header-anchor" href="#_2-画面構成とビジュアル表示" aria-label="Permalink to “2. 画面構成とビジュアル表示”">​</a></h2><p>左右の 2 ペイン連動レイアウトを採用しており、各階層のフォルダーやファイルの容量割合を一目で把握できます。</p><h3 id="左ペイン-ツリーマップ-treemap-表示" tabindex="-1">左ペイン：ツリーマップ（Treemap）表示 <a class="header-anchor" href="#左ペイン-ツリーマップ-treemap-表示" aria-label="Permalink to “左ペイン：ツリーマップ（Treemap）表示”">​</a></h3><ul><li><strong>面積による直感的な表現</strong>：占有容量が大きいフォルダーやファイルほど、大きな四角形として描画されます。</li><li><strong>濃淡と境界線</strong>：現在のフォルダー内における相対的な容量の重みを濃淡で表現し、専用の枠線スタイルでフォルダーと通常ファイルを明確に区別します。</li></ul><h3 id="右ペイン-サイズ降順一覧" tabindex="-1">右ペイン：サイズ降順一覧 <a class="header-anchor" href="#右ペイン-サイズ降順一覧" aria-label="Permalink to “右ペイン：サイズ降順一覧”">​</a></h3><ul><li><strong>サイズ降順ソート</strong>：現在の階層のアイテムを大きい順にリストアップし、容量を圧迫している原因を素早く特定できます。</li><li><strong>割合プログレスバー</strong>：各行の下部にバーが表示され、現在の総容量に対する割合を直感的に確認できます。</li><li><strong>双方向連動ハイライト</strong>：左側のツリーマップまたは右側の一覧で項目を選択すると、もう一方のペインでも連動してハイライトされます。</li><li><strong>長いファイル名の自動スクロール</strong>：枠内に収まらない長いファイル名は、ホバー時や選択時に自動スクロール表示されます。</li></ul><h2 id="_3-ナビゲーションと操作方法" tabindex="-1">3. ナビゲーションと操作方法 <a class="header-anchor" href="#_3-ナビゲーションと操作方法" aria-label="Permalink to “3. ナビゲーションと操作方法”">​</a></h2><ul><li><strong>階層の移動</strong>： <ul><li><strong>フォルダーに入る</strong>：ツリーマップのカードまたは右側の一覧項目を左ダブルクリックして、そのフォルダーの内部構造を展開。</li><li><strong>親フォルダーに戻る</strong>：上部バーの「上へ」矢印をクリックするか、パンくずリストの任意の親フォルダーをクリック。</li></ul></li><li><strong>コンテキストアクションメニュー</strong>：任意のカードや一覧項目で右クリックすると、通常の検索結果と同じ <strong>アクションメニュー</strong>（開く、フルパスのコピー、エクスプローラーで表示、ごみ箱へ移動、完全削除）が展開されます。</li><li><strong>中クリックでの場所表示</strong>：中クリックすると、設定されたファイラーでその項目の場所が即座に開きます。</li><li><strong>QuickLook プレビューの連動</strong>：項目を選択して <code>Alt+P</code> を押すとプレビューパネルが展開され、選択した項目に合わせてリアルタイムに更新されます。</li></ul><h2 id="_4-集計基準とリアルタイム同期" tabindex="-1">4. 集計基準とリアルタイム同期 <a class="header-anchor" href="#_4-集計基準とリアルタイム同期" aria-label="Permalink to “4. 集計基準とリアルタイム同期”">​</a></h2><h3 id="集計の範囲と基準" tabindex="-1">集計の範囲と基準 <a class="header-anchor" href="#集計の範囲と基準" aria-label="Permalink to “集計の範囲と基準”">​</a></h3><ul><li><strong>既存インデックスの活用</strong>：Lertaro で有効化されているインデックス内の項目のみを集計し、追加のディスク I/O 走査は行いません。除外ルールに該当するファイルは集計対象外です。</li><li><strong>論理サイズでの集計</strong>：ファイルの実際の論理サイズを集計し、ハードリンクデータは 1 回のみカウントして重複を防ぎます。</li><li><strong>隠しファイルとシステムファイル</strong>：隠しファイルは通常どおり集計・表示されます。システムファイルは親フォルダーの合計容量に合算されます。</li></ul><h3 id="リアルタイム同期と自動復帰" tabindex="-1">リアルタイム同期と自動復帰 <a class="header-anchor" href="#リアルタイム同期と自動復帰" aria-label="Permalink to “リアルタイム同期と自動復帰”">​</a></h3><ul><li><strong>変更のリアルタイム反映</strong>：ファイルの追加・変更・削除が発生すると、インデックスの更新通知を受け取って自動的かつスムーズに画面を更新します。</li><li><strong>パスの自動復帰</strong>：閲覧中のフォルダーが外部から削除・名前変更された場合でも、ストレージ分析はアクセス可能な親フォルダーへ自動的かつ安全に戻ります。</li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};